        mov     ax, [moview__viewPlace__col]
        mov     [moview__curCol], ax
; ---- if ( curCol > lineLength( curLine ) ) curCol = lineLength( curLine )
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [moview__curLine]
        mov     [lineLength__ln], ax
        call    lineLength
        mov     ax, [lineLength__ret]
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jbe     .L192                       ; unsigned >
        mov     ax, [moview__curLine]
        mov     [lineLength__ln], ax
        call    lineLength
        mov     ax, [lineLength__ret]
        mov     [moview__curCol], ax
.L192:
; ---- viewFollow()
        call    moview__viewFollow
        ret

; ============================================== sub viewRender ====

viewRender:
; ---- for ( u16 y = 0; y < height; y++ ) {
        mov     word [viewRender__y], 0
.L195:
        mov     ax, [viewRender__y]
        mov     bx, [moview__height]
        cmp     ax, bx
        jb      .L198                       ; unsigned <
        jmp     .L197
.L198:
; ---- ln = top + y
        mov     ax, [moview__top]
        mov     bx, [viewRender__y]
        add     ax, bx
        mov     [viewRender__ln], ax
; ---- n = 0
        mov     word [viewRender__n], 0
; ---- if ( ln < textLines() ) n = lineSlice( ln, left, width, addr( row ) )
        mov     ax, [viewRender__ln]
        push    ax                          ; save lhs: rhs is not a leaf
        call    textLines
        mov     ax, [textLines__ret]
        mov     bx, ax
        pop     ax
        cmp     ax, bx
        jae     .L199                       ; unsigned <
        mov     ax, [viewRender__ln]
        mov     [lineSlice__ln], ax
        mov     ax, [moview__left]
        mov     [lineSlice__col], ax
        mov     ax, [moview__width]
        mov     [lineSlice__count], ax
        mov     ax, moview__row             ; link-time constant
        mov     [lineSlice__at], ax
        call    lineSlice
        mov     ax, [lineSlice__ret]
        mov     [viewRender__n], ax
.L199:
; ---- viewRow( y, addr( row ), n )
        mov     ax, [viewRender__y]
        mov     [viewRow__y], ax
        mov     ax, moview__row             ; link-time constant
        mov     [viewRow__at], ax
        mov     ax, [viewRender__n]
        mov     [viewRow__n], ax
        call    viewRow
.L196:
        inc     word [viewRender__y]
        jmp     .L195
.L197:
        ret

; ============================================== sub viewRow ====

viewRow:
; ---- for ( u16 i = 0; i < n; i++ ) {
        mov     word [viewRow__i], 0
.L202:
        mov     ax, [viewRow__i]
        mov     bx, [viewRow__n]
        cmp     ax, bx
        jae     .L204                       ; unsigned <
; ---- putChar( peek8( at + i ) )
        mov     ax, [viewRow__at]
        mov     bx, [viewRow__i]
        add     ax, bx
        mov     bx, ax
        mov     al, [bx]                    ; peek8 - unchecked, by design
        mov     [putChar__c], al            ; u8 -> u8, no widening
        call    putChar
.L203:
        inc     word [viewRow__i]
        jmp     .L202
.L204:
; ---- putChar( '|' )
        mov     byte [putChar__c], 124
        call    putChar
; ---- newline()
        call    newline
        ret

; ============================================== sub showWhere ====

showWhere:
; ---- putNumber( viewTop() )
        call    viewTop
        mov     ax, [viewTop__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( viewLeft() )
        call    viewLeft
        mov     ax, [viewLeft__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ============================================== sub showAt ====

showAt:
; ---- putNumber( viewLine() )
        call    viewLine
        mov     ax, [viewLine__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( viewCol() )
        call    viewCol
        mov     ax, [viewCol__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        pop     es
        ret

